rtk proxy node -e '
const fs = require("fs"), crypto = require("crypto"), yaml = require("yaml");
const { evaluateGate, METRICS } = require("./scripts/check-promptfoo-quality-gate.js");
const sha = p => crypto.createHash("sha256").update(fs.readFileSync(p)).digest("hex");
const root = "../";
const files = ["webpage-ecological.yaml","account-security-alert.yaml","guard-mode.yaml"].map(f => "evals/promptfoo/cases/" + f);
const cases = files.flatMap(file => yaml.parse(fs.readFileSync(root + file,"utf8")).map((c,index) => ({case_id:c.vars.case_id, file, index, vars:c.vars, assertions:c.assert, snapshot_sha256:crypto.createHash("sha256").update(JSON.stringify(c)).digest("hex")})));
const coverage = Object.fromEntries(METRICS.map(m => [m,{product_template:0,synthetic_holdout:0,total:0}]));
for (const c of cases) for (const a of c.assertions) { coverage[a.metric][c.vars.source_type]++; coverage[a.metric].total++; }
const reportPath = "evals/promptfoo/results/latest.json";
const report = JSON.parse(fs.readFileSync(root + reportPath, "utf8"));
const rows = report.results.results || report.results;
const resultIds = rows.map(r => r.testCase?.vars?.case_id);
const failures = rows.flatMap(r => (r.gradingResult?.componentResults || []).filter(c=>c.pass === false).map(c => ({case_id:r.testCase?.vars?.case_id,metric:c.assertion?.metric,reason:c.reason})));
const sourcePaths = [...files, "evals/promptfoo/promptfooconfig.yaml","evals/promptfoo/prompts/current.chat.prompt.json","evals/promptfoo/AI_BEHAVIOR_EVALUATION_GUIDE.md","tutor-system/scripts/check-promptfoo-quality-gate.js","tutor-system/scripts/guard-mode-contract-rubric.js","tutor-system/scripts/response-length-rubric.js","tutor-system/src/services/aiService.ts","tutor-system/src/services/ecologicalTutorCall.ts","tutor-system/src/services/prompts/responsePolicy.ts",...fs.readdirSync(root+"evals/promptfoo/rubrics").filter(f=>f.endsWith(".md")).map(f=>"evals/promptfoo/rubrics/"+f)];
const snapshot = {
 artifact_kind:"offline_behavior_formalization",
 intent:"Preserve current evaluation inputs, assertion inventory, source versions, and offline saved-report re-scoring; this is not a new model run.",
 recorded_at_utc:new Date().toISOString(),
 source_commit:"96238a6",
 scope:{new_model_calls:0,prompt_changes:0,case_changes:0,rubric_changes:0,production_browser_checks:"not_run",prior_worktree:"existing unrelated untracked files; skill committed; formalization documents being authored"},
 method:{operation:"evaluateGate(JSON.parse(saved report)) plus YAML inventory",module:"tutor-system/scripts/check-promptfoo-quality-gate.js",node:process.version,threshold:0.8,raw_runs:"Original saved report is retained in git at source_commit and sha256 below; no raw LLM output rewritten."},
 configured_evaluation:yaml.parse(fs.readFileSync(root+"evals/promptfoo/promptfooconfig.yaml","utf8")),
 holdout_status:"Synthetic origin labels retained; independent historical authorship/exposure not verified. These cases have now been inspected by this agent and are not unseen holdouts for its subsequent prompt tuning.",
 sources:sourcePaths.map(path=>({path,sha256:sha(root+path),git_reference:"96238a6:"+path})),
 inventory:{total_cases:cases.length,total_assertions:cases.reduce((n,c)=>n+c.assertions.length,0),case_files:files.map(file=>({file,count:cases.filter(c=>c.file===file).length})),metric_coverage:coverage,declared_case_roles:cases.filter(c=>c.vars.case_role).length,pairs:[...new Set(cases.map(c=>c.vars.pair_id).filter(Boolean))],transition_marked_cases:cases.filter(c=>c.vars.transition_from).map(c=>c.case_id)},
 cases,
 saved_report:{path:reportPath,sha256:sha(root+reportPath),git_reference:"96238a6:"+reportPath,total_results:rows.length,case_ids:resultIds,missing_current_case_ids:cases.map(c=>c.case_id).filter(id=>!resultIds.includes(id)),extra_case_ids:resultIds.filter(id=>!cases.some(c=>c.case_id===id)),failed_components:failures},
 gate_result:evaluateGate(report)
};
console.log(JSON.stringify(snapshot,null,2));
'
